import { builtinModules } from "node:module";
import process from "node:process";

import { crivWasmBytesPlugin } from "@criv/editor-state/esbuild";
import esbuild from "esbuild";

const args = new Set(process.argv.slice(2));
const production = args.has("--production");

/** Modules that Obsidian provides to the plugin at runtime. */
const obsidianExternals = [
  "obsidian",
  "electron",
  "@codemirror/autocomplete",
  "@codemirror/collab",
  "@codemirror/commands",
  "@codemirror/language",
  "@codemirror/lint",
  "@codemirror/search",
  "@codemirror/state",
  "@codemirror/view",
  "@lezer/common",
  "@lezer/highlight",
  "@lezer/lr",
  ...builtinModules,
  ...builtinModules.map((name) => `node:${name}`),
];

const context = await esbuild.context({
  banner: {
    js: "/* Generated by esbuild from src/main.ts; run npm run build in this plugin directory. */",
  },
  entryPoints: ["src/main.ts"],
  bundle: true,
  platform: "node",
  external: obsidianExternals,
  plugins: [crivWasmBytesPlugin],
  format: "cjs",
  target: "es2018",
  logLevel: "info",
  sourcemap: production ? false : "inline",
  treeShaking: true,
  outfile: "main.js",
  minify: production,
});

if (args.has("--watch")) {
  await context.watch();
} else {
  await context.rebuild();
  await context.dispose();
}
